      section.createDiv({
        cls: "wechat-publisher-style-empty",
        text: "\u8FD8\u6CA1\u6709\u4FDD\u5B58\u8FC7\u683C\u5F0F\u65B9\u6848\u3002\u5148\u53BB\u9AD8\u7EA7\u5FAE\u8C03\u91CC\u8C03\u4E00\u5957\uFF0C\u518D\u4FDD\u5B58\u6210\u81EA\u5DF1\u7684\u65B9\u6848\u3002"
      });
