var import_obsidian8 = require("obsidian");
var UpdateAvailableModal = class extends import_obsidian8.Modal {
  constructor(plugin23, updateInfo) {
    super(plugin23.app);
    this.plugin = plugin23;
    this.updateInfo = updateInfo;
  }
  onOpen() {
    const { contentEl, titleEl } = this;
    titleEl.setText("\u53D1\u73B0\u65B0\u7248\u672C");
    contentEl.empty();
    contentEl.createEl("p", {
      text: `\u5F53\u524D\u7248\u672C\u662F ${this.updateInfo.currentVersion}\uFF0C\u68C0\u6D4B\u5230\u65B0\u7248\u672C ${this.updateInfo.version}\u3002`
    });
    const detailsEl = contentEl.createEl("div", {
      cls: "wechat-publisher-settings-note"
    });
    detailsEl.createEl("div", {
      text: "\u5F53\u524D\u5206\u53D1\u65B9\u5F0F\u4E0B\uFF0C\u5347\u7EA7\u5EFA\u8BAE\u901A\u8FC7\u4E0B\u8F7D\u6700\u65B0\u7248\u5B89\u88C5\u5305\u540E\u8986\u76D6\u63D2\u4EF6\u76EE\u5F55\u5B8C\u6210\u3002"
    });
    if (this.updateInfo.minAppVersion) {
      detailsEl.createEl("div", {
        text: `\u8BE5\u7248\u672C\u8981\u6C42\u7684\u6700\u4F4E Obsidian \u7248\u672C\uFF1A${this.updateInfo.minAppVersion}`
      });
    }
    if (this.updateInfo.publishedAt) {
      detailsEl.createEl("div", {
        text: `\u53D1\u5E03\u65F6\u95F4\uFF1A${this.updateInfo.publishedAt}`
      });
    }
    new import_obsidian8.Setting(contentEl).addButton((button) => {
      button.setButtonText("\u7A0D\u540E\u518D\u8BF4");
      button.onClick(() => {
        this.close();
      });
    }).addButton((button) => {
      button.setButtonText("\u8DF3\u8FC7\u6B64\u7248\u672C");
      button.onClick(async () => {
        this.plugin.settings.skippedUpdateVersion = this.updateInfo.version;
        await this.plugin.saveSettings();
        this.close();
      });
    }).addButton((button) => {
      button.setButtonText("\u53BB\u4E0B\u8F7D\u66F4\u65B0");
      button.setCta();
      button.onClick(() => {
        const url = this.updateInfo.downloadUrl || this.updateInfo.releaseNotesUrl;
        if (url) {
          this.plugin.openExternalUrl(url, "\u6253\u5F00\u66F4\u65B0\u9875\u9762\u5931\u8D25\uFF0C\u8BF7\u7A0D\u540E\u91CD\u8BD5\u3002");
        }
        this.close();
      });
    });
  }
  onClose() {
    this.contentEl.empty();
  }
};

